ntra con A. E. cerca de la Provost’s House de Trinity College."}}},{"book":"ulisse","id":"rds","collection":"core","name":"Royal Dublin Society","noteHash":"720cec257c013e2e784f34c00ccfde89","positionSource":"725a97f6f2f76aa41a194da9567ac553f892c8f40114a5ba03b310b3ed11967c","narrativeSource":"ea31350b7c6af2f19e4548516e011c977f362524b7acbd7e22e1deed806c6a52","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"The Royal Dublin Society complex is the destination of the viceregal procession and its bazaar.","it":"Il complesso della Royal Dublin Society è la destinazione del corteo vicereale e del bazar.","fr":"Le complexe de la Royal Dublin Society est la destination du cortège vice-royal et de son bazar.","es":"El complejo de la Royal Dublin Society es el destino del cortejo virreinal y de su bazar."}}},{"book":"ulisse","id":"star","collection":"core","name":"Star of the Sea","noteHash":"b67fb785aee92e9364ecae0708b0cce2","positionSource":"3866675283d3f0b7b5cb6d573542749c75b4376223bcf28bf3c4eff0bc0814e5","narrativeSource":"6f450757aa04be95e8908337362f2a20f16a5e04b8865e81fd718620bf0aebd9","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Sounds from the Star of the Sea church service enter the Sandymount scene.","it":"I suoni della funzione nella chiesa Star of the Sea entrano nella scena di Sandymount.","fr":"Les sons de l’office à l’église Star of the Sea parviennent à la scène de Sandymount.","es":"Los sonidos del oficio en la iglesia Star of the Sea llegan a la escena de Sandymount."}}},{"book":"ulisse","id":"stoney","collection":"core","name":"Stoneybatter","noteHash":"28c6feaf15f3c05739a81b3edcd41d61","positionSource":"a58b4795cf3d805511af31a20bd8f3e8706fd09da2374d7d1f440d192225dcdc","narrativeSource":"db6c0c2e8aad17cc005526d02c8046f2b14f0dc12e611a6e7c85931500eb3921","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"The narrator and Joe walk through Stoneybatter on their way towards the pub.","it":"Il narratore e Joe attraversano Stoneybatter mentre si dirigono verso il pub.","fr":"Le narrateur et Joe traversent Stoneybatter en se dirigeant vers le pub.","es":"El narrador y Joe atraviesan Stoneybatter camino del pub."}}}]'::jsonb; expected integer := 23;
begin
 if (select count(*) from public.place_descriptions d join jsonb_to_recordset(p) x(book text,id text,collection text,"noteHash" text,"positionSource" text,"narrativeSource" text,description jsonb) on d.book_id=x.book and d.place_id=x.id and d.collection=x.collection where md5(coalesce(d.note,''))=x."noteHash" and d.position_source_id::text=x."positionSource" and d.narrative_source_id::text is not distinct from x."narrativeSource" and (not (coalesce(d.metadata,'{}'::jsonb) ? 'positionDescription') or d.metadata->'positionDescription'=x.description)) <> expected then raise exception 'A source or summary changed; no updates applied'; end if;
 update public.place_descriptions d set metadata=jsonb_set(coalesce(d.metadata,'{}'::jsonb),'{positionDescription}',x.description,true) from jsonb_to_recordset(p) x(book text,id text,collection text,description jsonb) where d.book_id=x.book and d.place_id=x.id and d.collection=x.collection;
end $revision$;
commit;
